"""Random strings over a tiny alphabet, so repeats (including the abba
pattern) are frequent."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    alphabet = rng.choice(["ab", "abc", "abcd", "abcdefg"])
    n = rng.randint(0, 20)
    return {"name": "%d characters over '%s' #%d" % (n, alphabet, index),
            "stdin": "".join(rng.choice(alphabet) for _ in range(n)) + "\n"}
